// The official add-on directory of propwashfpv.com (website design 0.6.0, 3.6; share codes PW3, 3.6 and 3.16).
//
//   assets/data/addons/registry.json   the allocation list, written by hand: namespaces and short ids of the listed
//                                      add-ons, append only (a short id is never given again, a withdrawn add-on
//                                      keeps its entry), with the page texts and the hosted web export
//   assets/data/addons/directory.json  generated by tools/build-addons.mjs (format 1): every add-on with its short
//                                      id, names, Modrinth and CurseForge slugs and its versions with the parts
//                                      table checksum and the hosted data; tools/sharecode/sync_directory.py of
//                                      Propwash makes the directory copy in the mod from it
//   assets/data/addons/<ns>/<version>/ the hosted web export of a listed version (manifest, parts, chemistries,
//                                      mounts, parts table), made from the published jar by the same code as the
//                                      jar loader of the configurator
//
// Only released add-ons are listed. Downloads are CurseForge and Modrinth only (assets/data/platforms.json).
// Validation shared by tools/test-addons.mjs and tools/test-directory.mjs.

export const REGISTRY_URL = new URL('../../data/addons/registry.json', import.meta.url);
export const DIRECTORY_URL = new URL('../../data/addons/directory.json', import.meta.url);
export const SOURCE = 'propwashfpv.com/addons/';
export const KINDS = Object.freeze(['parts', 'modes', 'accessories', 'tools']);
export const STATUSES = Object.freeze(['listed', 'withdrawn']);
export const BASE_NAMESPACE = 'propwash';
export const BASE_SHORT_ID = 1;
const NAMESPACE = /^[a-z0-9_.-]{1,64}$/;
const VERSION = /^\d+\.\d+\.\d+$/;
const MODRINTH = /^https:\/\/modrinth\.com\/mod\/([a-z0-9_-]+)$/;
const CURSEFORGE = /^https:\/\/www\.curseforge\.com\/minecraft\/mc-mods\/([a-z0-9_-]+)$/;

const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const versionKey = (v) => v.split('.').map((n) => Number.parseInt(n, 10));
export function compareVersions(a, b) {
  const x = versionKey(a);
  const y = versionKey(b);
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
}

/** The slugs of a product's CurseForge and Modrinth pages in platforms.json, or nulls. */
export function slugs(platforms, product) {
  const p = platforms && platforms.products && platforms.products[product];
  const m = p && p.modrinth && MODRINTH.exec(p.modrinth.url || '');
  const c = p && p.curseforge && CURSEFORGE.exec(p.curseforge.url || '');
  return { modrinth: m ? m[1] : null, curseforge: c ? c[1] : null };
}

/** Problems of registry.json (empty when valid); `platforms` is assets/data/platforms.json. */
export function validateRegistry(json, platforms) {
  const out = [];
  if (!isObject(json) || json.schema !== 1) return ['schema must be 1'];
  const base = json.base;
  if (!isObject(base) || base.namespace !== BASE_NAMESPACE || base.short_id !== BASE_SHORT_ID) out.push('base must be propwash with short id 1');
  if (!Array.isArray(json.addons)) return [...out, 'addons must be a list'];
  const namespaces = new Set([BASE_NAMESPACE]);
  const shortIds = new Set([BASE_SHORT_ID]);
  json.addons.forEach((a, i) => {
    const at = `addons[${i}]${a && a.namespace ? ` (${a.namespace})` : ''}`;
    if (!isObject(a)) {
      out.push(`${at}: object expected`);
      return;
    }
    if (typeof a.namespace !== 'string' || !NAMESPACE.test(a.namespace)) out.push(`${at}: namespace must be a mod id (a–z, 0–9, _ . -)`);
    else if (a.namespace === BASE_NAMESPACE) out.push(`${at}: the namespace propwash belongs to Propwash and is never given to an add-on`);
    else if (namespaces.has(a.namespace)) out.push(`${at}: namespace given twice`);
    namespaces.add(a.namespace);
    if (!Number.isInteger(a.short_id) || a.short_id < 2) out.push(`${at}: short_id must be a whole number from 2 (1 is Propwash)`);
    else if (shortIds.has(a.short_id)) out.push(`${at}: short_id ${a.short_id} given twice`);
    shortIds.add(a.short_id);
    if (typeof a.name !== 'string' || !a.name.trim()) out.push(`${at}: name missing`);
    if (typeof a.official !== 'boolean') out.push(`${at}: official must be true or false`);
    if (!STATUSES.includes(a.status)) out.push(`${at}: status must be one of ${STATUSES.join(', ')}`);
    if (!/^\d{4}-\d{2}$/.test(a.since || '')) out.push(`${at}: since must look like 2026-10`);
    if (!Array.isArray(a.kinds) || !a.kinds.length || a.kinds.some((k) => !KINDS.includes(k))) out.push(`${at}: kinds must be some of ${KINDS.join(', ')}`);
    if (typeof a.page !== 'string' || !/^addons\/[a-z0-9-]+\/$/.test(a.page)) out.push(`${at}: page must be addons/<name>/`);
    if (typeof a.license !== 'string' || !a.license) out.push(`${at}: license missing`);
    if (!isObject(a.requires) || typeof a.requires.propwash !== 'string' || !VERSION.test(a.requires.propwash)) {
      out.push(`${at}: requires.propwash must be the lowest Propwash version, like 0.6.0`);
    }
    if (typeof a.platforms !== 'string' || !(platforms && platforms.products && platforms.products[a.platforms])) {
      out.push(`${at}: platforms must name a product of assets/data/platforms.json (downloads only on CurseForge and Modrinth)`);
    } else {
      const s = slugs(platforms, a.platforms);
      if (!s.modrinth || !s.curseforge) out.push(`${at}: the platforms entry needs a Modrinth and a CurseForge page`);
    }
    for (const key of ['modrinth', 'curseforge', 'download', 'downloads', 'github', 'url']) {
      if (key in a) out.push(`${at}: ${key} does not belong here – download addresses come only from assets/data/platforms.json`);
    }
    if (!Array.isArray(a.versions) || !a.versions.length || a.versions.some((v) => typeof v !== 'string' || !VERSION.test(v))) {
      out.push(`${at}: versions must list the released versions, like ["1.2.0"]`);
    } else {
      for (let k = 1; k < a.versions.length; k++) if (compareVersions(a.versions[k - 1], a.versions[k]) >= 0) out.push(`${at}: versions must rise`);
    }
    if (a.web_export !== undefined) {
      const w = a.web_export;
      if (!isObject(w) || typeof w.version !== 'string' || !Array.isArray(a.versions) || !a.versions.includes(w.version)) {
        out.push(`${at}: web_export.version must be one of versions`);
      } else if (w.path !== `assets/data/addons/${a.namespace}/${w.version}/`) {
        out.push(`${at}: web_export.path must be assets/data/addons/${a.namespace}/${w.version}/`);
      }
    }
    if (!isObject(a.text) || typeof a.text.en !== 'string' || !a.text.en || typeof a.text.de !== 'string' || !a.text.de) {
      out.push(`${at}: text needs en and de`);
    }
  });
  return out;
}

/**
 * Problems of a newer registry against an older one (empty when the newer only appends): every add-on of the older
 * list keeps its place, namespace and short id; versions are only added; nothing gets a used short id.
 */
export function appendOnly(older, newer) {
  const out = [];
  const before = (older && older.addons) || [];
  const after = (newer && newer.addons) || [];
  before.forEach((a, i) => {
    const b = after[i];
    if (!b) {
      out.push(`${a.namespace}: removed – a listed add-on stays (status withdrawn)`);
      return;
    }
    if (b.namespace !== a.namespace || b.short_id !== a.short_id) out.push(`addons[${i}]: was ${a.namespace} (${a.short_id}), now ${b.namespace} (${b.short_id}) – entries are never changed or moved`);
    const versions = new Set(b.versions || []);
    for (const v of a.versions || []) if (!versions.has(v)) out.push(`${a.namespace}: version ${v} removed – old versions stay listed`);
  });
  return out;
}

/**
 * Problems of a newer parts table against an older one (empty when it only appends): every entry keeps its number and
 * id; entries may only get a "deprecated" with a replacement.
 */
export function tableAppendOnly(older, newer) {
  const out = [];
  for (const [kind, entries] of Object.entries((older && older.parts) || {})) {
    const next = ((newer && newer.parts) || {})[kind] || [];
    entries.forEach((e, i) => {
      const n = next[i];
      if (!n) out.push(`${kind} #${i + 1} ${e.id}: removed`);
      else if (n.id !== e.id) out.push(`${kind} #${i + 1}: was ${e.id}, now ${n.id} – numbers are never given again`);
      else if (n.since !== e.since) out.push(`${kind} #${i + 1} ${e.id}: since changed from ${e.since} to ${n.since}`);
      else if (e.deprecated && n.deprecated !== e.deprecated) out.push(`${kind} #${i + 1} ${e.id}: deprecated taken back`);
    });
  }
  if (older && newer && older.short_id !== newer.short_id && older.short_id != null) out.push(`short_id changed from ${older.short_id} to ${newer.short_id}`);
  return out;
}

/** The listed add-ons of the registry (withdrawn ones stay in the file but are not shown). */
export const listed = (registry) => ((registry && registry.addons) || []).filter((a) => a.status === 'listed');

/**
 * directory.json (format 1) from the registry, platforms.json and the hosted versions ({namespace: {version:
 * manifest}}); Propwash comes first with the version of platforms.json and the base catalog.
 */
export function buildDirectory(registry, platforms, hosted, propwash) {
  const name = (n) => ({ en_us: n, de_de: n });
  const pw = slugs(platforms, registry.base.platforms);
  const addons = [{
    namespace: BASE_NAMESPACE, short_id: BASE_SHORT_ID, name: name(registry.base.name), official: true, modrinth: pw.modrinth, curseforge: pw.curseforge,
    versions: [{ version: platforms.products[registry.base.platforms].version, table_crc: propwash.table_crc, table_entries: propwash.table_entries, catalog: 'assets/data/configurator/' }],
  }];
  for (const a of registry.addons) {
    const s = slugs(platforms, a.platforms);
    const versions = (a.versions || []).map((v) => {
      const m = hosted[a.namespace] && hosted[a.namespace][v];
      const out = { version: v };
      if (m) {
        out.table_crc = m.table_crc;
        out.table_entries = m.table_entries;
        out.catalog = `assets/data/addons/${a.namespace}/${v}/`;
        out.jar = m.jar;
      }
      return out;
    });
    addons.push({
      namespace: a.namespace, short_id: a.short_id, name: name(a.name), official: a.official, status: a.status, modrinth: s.modrinth, curseforge: s.curseforge,
      page: a.page, versions,
    });
  }
  return { format: 1, source: SOURCE, addons };
}

let pending = null;

/** Fetches registry.json and directory.json (same origin) once: {registry, directory}. */
export function loadDirectory() {
  if (!pending) {
    const get = (url) => fetch(url, { credentials: 'same-origin' }).then((r) => {
      if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
      return r.json();
    });
    pending = Promise.all([get(REGISTRY_URL), get(DIRECTORY_URL)]).then(([registry, directory]) => ({ registry, directory }))
      .catch((e) => {
        pending = null;
        throw e;
      });
  }
  return pending;
}
